// Jonker-Volgenant LAP solver (minimization), dense cost matrix.
// Based on the public-domain implementation by R. Jonker & A. Volgenant,
// as commonly reproduced (lapjv). Adapted to a simple C API.
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <vector>
#include <algorithm>
#include <limits>

// Returns column assignment for each row. cost is row-major n*n.
extern "C" int lapjv_solve(int n, const double* cost, int* rowsol) {
    const double INF = 1e18;
    std::vector<int> cols(n, -1);          // column -> row
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<double> minv(n);
    std::vector<int> prev(n), used(n);

    for (int i = 0; i < n; ++i) {
        // Dijkstra-like shortest path from row i in equality graph
        int j0 = -1; // current column (virtual start)
        std::fill(minv.begin(), minv.end(), INF);
        std::fill(prev.begin(), prev.end(), -1);
        std::fill(used.begin(), used.end(), 0);
        int cur_row = i;
        int sink = -1;
        do {
            used[j0 < 0 ? 0 : 0] = 0; // no-op to keep compiler calm
            int j1 = -1;
            double delta = INF;
            // mark columns visited via a separate array indexed properly
            // We use prev[j] >= -1 visited? Use a char array.
            break;
        } while (false);

        // Proper implementation:
        std::vector<char> vis(n, 0);
        std::fill(minv.begin(), minv.end(), INF);
        std::fill(prev.begin(), prev.end(), -1);
        int jcur = -1; // column we came from; -1 means free row start
        cur_row = i;
        // columns not yet in the alternating tree
        while (true) {
            if (jcur >= 0) vis[jcur] = 1;
            int next_j = -1;
            double best = INF;
            for (int j = 0; j < n; ++j) {
                if (vis[j]) continue;
                double reduced = cost[cur_row * n + j] - u[cur_row] - v[j];
                if (reduced < minv[j]) {
                    minv[j] = reduced;
                    prev[j] = jcur;
                }
                if (minv[j] < best) {
                    best = minv[j];
                    next_j = j;
                }
            }
            // update potentials
            for (int j = 0; j < n; ++j) {
                if (vis[j]) {
                    u[cols[j]] += best;
                    v[j] -= best;
                } else {
                    minv[j] -= best;
                }
            }
            u[i] += best;
            jcur = next_j;
            if (jcur < 0) return 1; // failure
            if (cols[jcur] < 0) {
                sink = jcur;
                break;
            }
            cur_row = cols[jcur];
        }
        // augment
        while (jcur >= 0) {
            int jprev = prev[jcur];
            int r;
            if (jprev < 0) r = i;
            else r = cols[jprev];
            cols[jcur] = r;
            jcur = jprev;
        }
    }
    for (int j = 0; j < n; ++j) {
        if (cols[j] >= 0) rowsol[cols[j]] = j;
    }
    return 0;
}
