def solve(C):
    n = C.shape[0]
    Cc = np.ascontiguousarray(C, dtype=np.float64)
    rowsol = np.empty(n, dtype=np.int32)
    rc = libh.lapjv_solve(n, Cc.ctypes.data_as(ctypes.POINTER(ctypes.c_double)),
                          rowsol.ctypes.data_as(ctypes.POINTER(ctypes.c_int)))
