{"command":"cat > jv.cpp << 'EOF'
// Column-reduction + shortest-augmenting-path assignment (Jonker-Volgenant style).
// Minimization. cost row-major n*n.
#include <cstdint>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstring>

static const double BIG = 1e100;

extern "C" int jv_solve(int n, const double* cost, int* col_of_row) {
    std::vector<double> u(n), v(n, 0.0);
    std::vector<int> row_of_col(n, -1);
    std::vector<double> minv(n);
    std::vector<int> pred(n);
    std::vector<char> seen(n);

    for (int i = 0; i < n; ++i) {
        // column reduction init: set u[i] = min_j cost
        double mn = cost[i * (int64_t)n];
        for (int j = 1; j < n; ++j) {
            double c = cost[i * (int64_t)n + j];
            if (c < mn) mn = c;
        }
        u[i] = mn;
    }
    // greedy initial matching
    std::vector<char> col_taken(n, 0);
    int matched = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (!col_taken[j] && cost[i * (int64_t)n + j] - u[i] - v[j] <= 1e-12) {
                row_of_col[j] = i;
                col_of_row[i] = j;
                col_taken[j] = 1;
                matched++;
                break;
            }
        }
        if (!col_taken[col_of_row[i]] && col_of_row[i] < 0) {
            col_of_row[i] = -1;
        }
    }
    // reset col_of_row properly
    std::fill(col_of_row, col_of_row + n, -1);
    for (int j = 0; j < n; ++j) if (row_of_col[j] >= 0) col_of_row[row_of_col[j]] = j;

    for (int i = 0; i < n; ++i) {
        if (col_of_row[i] >= 0) continue;
        std::fill(minv.begin(), minv.end(), BIG);
        std::fill(seen.begin(), seen.end(), 0);
        std::fill(pred.begin(), pred.end(), -1);
        int jcur = -1;
        int freecol = -1;
        int cur = i;
        // Dijkstra
        while (true) {
            int jbest = -1;
            double best = BIG;
            int64_t base = (int64_t)cur * n;
            double ui = u[cur];
            for (int j = 0; j < n; ++j) {
                if (seen[j]) continue;
                double red = cost[base + j] - ui - v[j];
                if (red < minv[j]) {
                    minv[j] = red;
                    pred[j] = jcur;
                }
                if (minv[j] < best) {
                    best = minv[j];
                    jbest = j;
                }
            }
            if (jbest < 0) return 1;
            for (int j = 0; j < n; ++j) {
                if (seen[j]) {
                    int r = row_of_col[j];
                    u[r] += best;
                    v[j] -= best;
                } else {
                    minv[j] -= best;
                }
            }
            u[i] += best;
            jcur = jbest;
            seen[jcur] = 1;
            if (row_of_col[jcur] < 0) {
                freecol = jcur;
                break;
            }
            cur = row_of_col[jcur];
        }
        // augment
        int j = freecol;
        while (j >= 0) {
            int jp = pred[j];
            int r = (jp < 0) ? i : row_of_col[jp];
            row_of_col[j] = r;
            col_of_row[r] = j;
            j = jp;
        }
    }
    return 0;
}
