#include <stdlib.h>
#include <string.h>
#include <float.h>
#include <stdint.h>

/* Hungarian algorithm, minimization, O(n^3). Returns 0 on success.
   col_of_row[i] = assigned column. */
int hungarian(int n, const double* cost, int* col_of_row) {
    double* u = (double*)calloc(n + 1, sizeof(double));
    double* v = (double*)calloc(n + 1, sizeof(double));
    int* p = (int*)calloc(n + 1, sizeof(int));
    int* way = (int*)calloc(n + 1, sizeof(int));
    double* minv = (double*)malloc((n + 1) * sizeof(double));
    char* used = (char*)malloc((n + 1) * sizeof(char));
    if (!u || !v || !p || !way || !minv || !used) return 1;

    for (int i = 1; i <= n; ++i) {
        p[0] = i;
        int j0 = 0;
        for (int j = 0; j <= n; ++j) { minv[j] = DBL_MAX; used[j] = 0; }
        do {
            used[j0] = 1;
            int i0 = p[j0];
            double delta = DBL_MAX;
            int j1 = 0;
            const double* row = cost + (int64_t)(i0 - 1) * n;
            double ui = u[i0];
            for (int j = 1; j <= n; ++j) {
                if (used[j]) continue;
                double cur = row[j - 1] - ui - v[j];
                if (cur < minv[j]) { minv[j] = cur; way[j] = j0; }
                if (minv[j] < delta) { delta = minv[j]; j1 = j; }
            }
            for (int j = 0; j <= n; ++j) {
                if (used[j]) { u[p[j]] += delta; v[j] -= delta; }
                else minv[j] -= delta;
            }
            j0 = j1;
        } while (p[j0] != 0);
        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0 != 0);
    }
    for (int j = 1; j <= n; ++j) {
        if (p[j] > 0) col_of_row[p[j] - 1] = j - 1;
    }
    free(u); free(v); free(p); free(way); free(minv); free(used);
    return 0;
}
