#include <math.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/* Heuristic dual ascent + auction-like assignment for min-cost assignment.
   Returns column for each row. Not guaranteed first try; we loop phases. */
int dual_assign(int n, const double* C, int* col_of, int max_passes) {
    double* u = (double*)calloc(n, sizeof(double));
    double* v = (double*)calloc(n, sizeof(double));
    int* row_of = (int*)malloc(n * sizeof(int));
    for (int j = 0; j < n; ++j) row_of[j] = -1;
    for (int i = 0; i < n; ++i) col_of[i] = -1;

    /* init u[i] = min_j C[i,j] */
    for (int i = 0; i < n; ++i) {
        const double* row = C + (int64_t)i * n;
        double mn = row[0];
        for (int j = 1; j < n; ++j) if (row[j] < mn) mn = row[j];
        u[i] = mn;
    }
    /* init v[j] = min over i of C[i,j]-u[i] */
    for (int j = 0; j < n; ++j) {
        double mn = C[j] - u[0];
        for (int i = 1; i < n; ++i) {
            double r = C[(int64_t)i * n + j] - u[i];
            if (r < mn) mn = r;
        }
        v[j] = mn;
    }

    for (int pass = 0; pass < max_passes; ++pass) {
        for (int j = 0; j < n; ++j) row_of[j] = -1;
        for (int i = 0; i < n; ++i) col_of[i] = -1;
        int matched = 0;
        /* greedy on tight edges, row order */
        for (int i = 0; i < n; ++i) {
            const double* row = C + (int64_t)i * n;
            double ui = u[i];
            int best = -1;
            double bestv = 1e300;
            for (int j = 0; j < n; ++j) {
                if (row_of[j] >= 0) continue;
                double red = row[j] - ui - v[j];
                if (red < 1e-9 && red < bestv) { bestv = red; best = j; }
            }
            if (best >= 0) {
                row_of[best] = i;
                col_of[i] = best;
                matched++;
            }
        }
        if (matched == n) { free(u); free(v); free(row_of); return pass; }
        /* raise u of unmatched rows to create a new tight edge to a free or any column */
        for (int i = 0; i < n; ++i) {
            if (col_of[i] >= 0) continue;
            const double* row = C + (int64_t)i * n;
            double ui = u[i];
            double best = 1e300;
            int bj = 0;
            double second = 1e300;
            for (int j = 0; j < n; ++j) {
                double red = row[j] - ui - v[j];
                if (red < best) { second = best; best = red; bj = j; }
                else if (red < second) second = red;
            }
            /* increase u so best becomes tight, and bid a bit like auction to unique-ify */
            double inc = best;
            if (second < 1e299) {
                /* auction: pay second-best gap */
            }
            u[i] += best; /* now best edge tight */
            /* if column taken, this doesn't free it; also decrease v of contended columns */
        }
        /* decrease v on columns that are matched to make alternatives for unmatched:
           for each unmatched row, lower v of its best column by a small amount? 
           Instead: for every column, set v[j] = min over ALL rows of C-u, which restores dual feasibility
           and creates tight edges. */
        for (int j = 0; j < n; ++j) {
            double mn = 1e300;
            for (int i = 0; i < n; ++i) {
                double r = C[(int64_t)i * n + j] - u[i];
                if (r < mn) mn = r;
            }
            v[j] = mn;
        }
    }
    free(u); free(v); free(row_of);
    return -1;
}
