#include <stdint.h>
#include <string.h>
#include <math.h>

/* Forward-reverse auction for the assignment problem (minimization).
   Bertsekas-style with epsilon scaling. */
int auction_solve(int n, const double* C, int* col_of, double eps_final) {
    double* price = (double*)calloc(n, sizeof(double));
    double* profit = (double*)calloc(n, sizeof(double)); /* row dual, stored positive as -u? we track bids */
    int* owner = (int*)malloc(n * sizeof(int));
    int* row_of = (int*)malloc(n * sizeof(int));
    for (int j = 0; j < n; ++j) owner[j] = -1;

    double cmax = 0.0;
    for (int i = 0; i < n; i += 1) {
        const double* row = C + (int64_t)i * n;
        for (int j = 0; j < n; j += 17) {
            double v = row[j];
            if (v > cmax) cmax = v;
        }
    }
    double eps = cmax / 4.0;
    if (eps < eps_final) eps = eps_final;

    int* un = (int*)malloc(n * sizeof(int));
    int* nun = (int*)malloc(n * sizeof(int));

    while (1) {
        for (int j = 0; j < n; ++j) owner[j] = -1;
        int n_un = n;
        for (int i = 0; i < n; ++i) un[i] = i;
        int guard = 0;
        int limit = n * 30;
        while (n_un > 0 && guard < limit) {
            guard++;
            int n_new = 0;
            for (int t = 0; t < n_un; ++t) {
                int i = un[t];
                const double* row = C + (int64_t)i * n;
                double best = 1e300, second = 1e300;
                int bj = 0;
                for (int j = 0; j < n; ++j) {
                    double v = row[j] + price[j];
                    if (v < best) { second = best; best = v; bj = j; }
                    else if (v < second) second = v;
                }
                double bid = price[bj] + (second - best) + eps;
                int prev = owner[bj];
                owner[bj] = i;
                price[bj] = bid;
                if (prev >= 0) nun[n_new++] = prev;
            }
            /* swap buffers */
            int* tmp = un; un = nun; nun = tmp;
            n_un = n_new;
        }
        if (n_un == 0) {
            if (eps <= eps_final * 1.001) break;
            eps *= 0.2;
            if (eps < eps_final) eps = eps_final;
            continue;
        } else {
            /* failed to assign at this eps; shrink and retry, keep prices */
            eps *= 0.5;
            if (eps < eps_final) {
                free(price); free(profit); free(owner); free(row_of); free(un); free(nun);
                return -1;
            }
        }
    }
    for (int j = 0; j < n; ++j) col_of[owner[j]] = j;
    free(price); free(profit); free(owner); free(row_of); free(un); free(nun);
    return 0;
}
