/* Jonker-Volgenant LAPMOD-style dense assignment, minimization.
   Adapted from the public-domain Pascal of Jonker & Volgenant (1987)
   via the widely used C translation (lap.h / lap.cpp, public domain).
   Compact single-function version. */
#include <stdlib.h>
#include <stdint.h>
#include <float.h>
#include <string.h>

#define BIG 1e100

int lapjv(int n, const double* cost, int* rowsol) {
    int* colsol = (int*)malloc(n * sizeof(int));
    double* u = (double*)malloc(n * sizeof(double));
    double* v = (double*)malloc(n * sizeof(double));
    int* free_rows = (int*)malloc(n * sizeof(int));
    int* pred = (int*)malloc(n * sizeof(int));
    double* d = (double*)malloc(n * sizeof(double));
    int* collist = (int*)malloc(n * sizeof(int));
    int* matches = (int*)malloc(n * sizeof(int));
    if (!colsol) return -1;

    /* COLUMN REDUCTION */
    for (int j = 0; j < n; ++j) { v[j] = BIG; colsol[j] = -1; }
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (int64_t)i * n;
        for (int j = 0; j < n; ++j) {
            double r = row[j];
            if (r < v[j]) { v[j] = r; colsol[j] = i; }
        }
    }
    /* reduction transfer */
    for (int i = 0; i < n; ++i) rowsol[i] = -1;
    int numfree = 0;
    for (int j = n - 1; j >= 0; --j) {
        int i = colsol[j];
        if (rowsol[i] < 0) {
            rowsol[i] = j;
        } else {
            /* column j is free-candidate; lower v to next-best for its row? mark free */
            colsol[j] = -1;
        }
    }
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) free_rows[numfree++] = i;

    /* init u */
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] >= 0) {
            u[i] = cost[(int64_t)i * n + rowsol[i]] - v[rowsol[i]];
        } else {
            const double* row = cost + (int64_t)i * n;
            double mn = BIG;
            for (int j = 0; j < n; ++j) {
                double r = row[j] - v[j];
                if (r < mn) mn = r;
            }
            u[i] = mn;
        }
    }

    /* AUGMENTING ROW REDUCTION (2 passes) */
    for (int pass = 0; pass < 2; ++pass) {
        int k = 0;
        int prevfree = numfree;
        numfree = 0;
        while (k < prevfree) {
            int i = free_rows[k++];
            const double* row = cost + (int64_t)i * n;
            double umin = BIG, usub = BIG;
            int j1 = 0;
            for (int j = 0; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < usub) {
                    if (h >= umin) { usub = h; }
                    else { usub = umin; umin = h; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            double ui = umin;
            if (ui < usub) v[j1] -= (usub - ui);
            else if (i0 >= 0) { j1 = -1; } /* no improvement, keep scanning for free */
            /* find minimum reduced, prefer free column */
            if (colsol[j1] >= 0 && colsol[j1] != i) {
                /* look for a free column at umin */
                int jfree = -1;
                for (int j = 0; j < n; ++j) {
                    if (colsol[j] < 0) {
                        double h = row[j] - v[j];
                        if (h <= umin + 1e-12) { jfree = j; break; }
                    }
                }
                if (jfree >= 0) j1 = jfree;
            }
            if (j1 >= 0 && colsol[j1] < 0) {
                colsol[j1] = i; rowsol[i] = j1; u[i] = ui;
            } else if (j1 >= 0 && colsol[j1] != i) {
                int i0b = colsol[j1];
                colsol[j1] = i; rowsol[i] = j1; u[i] = ui;
                if (rowsol[i0b] == j1) {
                    rowsol[i0b] = -1;
                    free_rows[numfree++] = i0b;
                }
            } else {
                free_rows[numfree++] = i;
            }
        }
    }

    /* AUGMENTATION: shortest paths for remaining free rows */
    for (int f = 0; f < numfree; ++f) {
        int freerow = free_rows[f];
        for (int j = 0; j < n; ++j) { d[j] = cost[(int64_t)freerow * n + j] - v[j] - u[freerow]; pred[j] = freerow; }
        int endofpath = -1;
        int last = 0;
        collist[0] = -1; /* unused */
        /* Dijkstra */
        char* todo = (char*)malloc(n);
        memset(todo, 1, n);
        int ntodo = n;
        while (1) {
            int jmin = -1; double dmin = BIG;
            for (int j = 0; j < n; ++j) if (todo[j] && d[j] < dmin) { dmin = d[j]; jmin = j; }
            if (jmin < 0) { free(todo); goto cleanup; }
            todo[jmin] = 0;
            if (colsol[jmin] < 0) { endofpath = jmin; break; }
            int i = colsol[jmin];
            const double* row = cost + (int64_t)i * n;
            double h0 = dmin + u[i] - (row[jmin] - v[jmin]); /* wait, better standard update */
            /* standard: d[j] = min(d[j], dmin + cost[i,j] - v[j] - (cost[i,jmin]-v[jmin]) ) but with u */
            double base = cost[(int64_t)i * n + jmin] - v[jmin];
            for (int j = 0; j < n; ++j) if (todo[j]) {
                double cred = cost[(int64_t)i * n + j] - v[j] - base;
                double nd = dmin + cred;
                if (nd < d[j]) { d[j] = nd; pred[j] = i; }
            }
        }
        /* update duals */
        double dlast = d[endofpath];
        for (int j = 0; j < n; ++j) if (!todo[j]) v[j] += d[j] - dlast;
        u[freerow] += dlast;
        free(todo);
        /* augment */
        int j = endofpath;
        while (1) {
            int i = pred[j];
            colsol[j] = i;
            int jprev = rowsol[i];
            rowsol[i] = j;
            if (i == freerow) break;
            j = jprev;
        }
    }
cleanup:
    free(colsol); free(u); free(v); free(free_rows); free(pred); free(d); free(collist); free(matches);
    return 0;
}
