{"command":"cat > lapjv.c << 'EOF'
/* Dense LAPJV (Jonker-Volgenant), minimization.
   Structure follows the public-domain implementation used by the `lap` package
   (column reduction, reduction transfer, augmenting row reduction, augmentation).
*/
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define LARGE 1.0e100

static int ccrrt(int n, const double *cost, int *free_rows, int *x, int *y, double *v) {
    char *unique = (char *)malloc((size_t)n);
    for (int i = 0; i < n; i++) {
        x[i] = -1;
        v[i] = LARGE;
        y[i] = 0;
    }
    for (int i = 0; i < n; i++) {
        const double *row = cost + (int64_t)i * n;
        for (int j = 0; j < n; j++) {
            double c = row[j];
            if (c < v[j]) {
                v[j] = c;
                y[j] = i;
            }
        }
    }
    memset(unique, 1, (size_t)n);
    for (int j = n - 1; j >= 0; j--) {
        int i = y[j];
        if (x[i] < 0) {
            x[i] = j;
        } else {
            unique[i] = 0;
            y[j] = -1;
        }
    }
    int n_free = 0;
    for (int i = 0; i < n; i++) {
        if (x[i] < 0) {
            free_rows[n_free++] = i;
        } else if (unique[i]) {
            int j = x[i];
            const double *row = cost + (int64_t)i * n;
            double min = LARGE;
            for (int j2 = 0; j2 < n; j2++) {
                if (j2 == j) continue;
                double c = row[j2] - v[j2];
                if (c < min) min = c;
            }
            v[j] -= min;
        }
    }
    free(unique);
    return n_free;
}

static int carr(int n, const double *cost, int n_free_rows, int *free_rows,
                int *x, int *y, double *v) {
    int current = 0;
    int new_free = 0;
    int rr_cnt = 0;
    while (current < n_free_rows) {
        rr_cnt++;
        int free_i = free_rows[current++];
        const double *row = cost + (int64_t)free_i * n;
        int j1 = 0;
        double v1 = row[0] - v[0];
        int j2 = -1;
        double v2 = LARGE;
        for (int j = 1; j < n; j++) {
            double c = row[j] - v[j];
            if (c < v2) {
                if (c >= v1) {
                    v2 = c;
                    j2 = j;
                } else {
                    v2 = v1;
                    v1 = c;
                    j2 = j1;
                    j1 = j;
                }
            }
        }
        int i0 = y[j1];
        double v1_new = v[j1] - (v2 - v1);
        int v1_lowers = v1_new < v[j1];
        if (rr_cnt < current * n) {
            if (v1_lowers) {
                v[j1] = v1_new;
            } else if (i0 >= 0 && j2 >= 0) {
                j1 = j2;
                i0 = y[j2];
            }
            if (i0 >= 0) {
                if (v1_lowers) {
                    free_rows[--current] = i0;
                } else {
                    free_rows[new_free++] = i0;
                }
            }
        } else {
            if (i0 >= 0) free_rows[new_free++] = i0;
        }
        x[free_i] = j1;
        y[j1] = free_i;
    }
    return new_free;
}

/* Shortest augmenting path. cols[0..hi) scanned-or-ready, cols[hi..n) unscanned.
   Returns the free column index. Updates pred and d. */
static int find_path(int n, const double *cost, int free_i, int *y, double *v,
                     int *pred, double *d, int *cols) {
    int lo = 0, hi = 0;
    for (int j = 0; j < n; j++) {
        cols[j] = j;
        pred[j] = free_i;
        d[j] = cost[(int64_t)free_i * n + j] - v[j];
    }
    while (1) {
        if (lo == hi) {
            double mind = d[cols[lo]];
            hi = lo + 1;
            for (int k = hi; k < n; k++) {
                int j = cols[k];
                double h = d[j];
                if (h <= mind) {
                    if (h < mind) {
                        hi = lo;
                        mind = h;
                    }
                    cols[k] = cols[hi];
                    cols[hi++] = j;
                }
            }
            for (int k = lo; k < hi; k++) {
                if (y[cols[k]] < 0) return cols[k];
            }
        }
        int j1 = cols[lo++];
        int i = y[j1];
        double mind = d[j1];
        const double *row = cost + (int64_t)i * n;
        double h = row[j1] - v[j1] - mind;
        for (int k = hi; k < n; k++) {
            int j = cols[k];
            double cred = row[j] - v[j] - h;
            if (cred < d[j]) {
                d[j] = cred;
                pred[j] = i;
                if (cred == mind) {
                    if (y[j] < 0) return j;
                    cols[k] = cols[hi];
                    cols[hi++] = j;
                }
            }
        }
    }
}

static int ca(int n, const double *cost, int n_free_rows, int *free_rows,
              int *x, int *y, double *v) {
    int *pred = (int *)malloc((size_t)n * sizeof(int));
    int *cols = (int *)malloc((size_t)n * sizeof(int));
    double *d = (double *)malloc((size_t)n * sizeof(double));
    for (int f = 0; f < n_free_rows; f++) {
        int i = free_rows[f];
        int j = find_path(n, cost, i, y, v, pred, d, cols);
        double mind = d[j];
        /* dual update on columns that were scanned (d < mind means fully processed;
           columns still in the tail have d >= mind and are not updated).
           Scanned columns were swapped toward the front, but not stably.
           Safer: update every column with d[j0] < mind. */
        for (int j0 = 0; j0 < n; j0++) {
            if (d[j0] < mind) v[j0] += d[j0] - mind;
        }
        /* augment */
        int i0;
        do {
            i0 = pred[j];
            y[j] = i0;
            int j0 = x[i0];
            x[i0] = j;
            j = j0;
        } while (i0 != i);
    }
    free(pred); free(cols); free(d);
    return 0;
}

int lapjv_solve(int n, const double *cost, int *rowsol) {
    int *x = rowsol;
    int *y = (int *)malloc((size_t)n * sizeof(int));
    double *v = (double *)malloc((size_t)n * sizeof(double));
    int *free_rows = (int *)malloc((size_t)n * sizeof(int));
    int ret = ccrrt(n, cost, free_rows, x, y, v);
    int it = 0;
    while (ret > 0 && it < 2) {
        ret = carr(n, cost, ret, free_rows, x, y, v);
        it++;
    }
    if (ret > 0) ca(n, cost, ret, free_rows, x, y, v);
    free(y); free(v); free(free_rows);
    return 0;
}

/* debug: return number of free rows after initialization phases */
int lapjv_free_count(int n, const double *cost) {
    int *x = (int *)malloc((size_t)n * sizeof(int));
    int *y = (int *)malloc((size_t)n * sizeof(int));
    double *v = (double *)malloc((size_t)n * sizeof(double));
    int *free_rows = (int *)malloc((size_t)n * sizeof(int));
    int ret = ccrrt(n, cost, free_rows, x, y, v);
    int after_cc = ret;
    int it = 0;
    while (ret > 0 && it < 2) {
        ret = carr(n, cost, ret, free_rows, x, y, v);
        it++;
    }
    free(x); free(y); free(v); free(free_rows);
    return after_cc * 10000 + ret;
}
