/* Gauss-Seidel auction with epsilon scaling, dense minimization.
   Processes one unassigned row at a time so prices stay consistent
   and the number of full scans is closer to the number of bids.
*/
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

int gsa_solve(int n, const double *C, int *col_of, double eps_final) {
    double *price = (double *)calloc((size_t)n, sizeof(double));
    int *owner = (int *)malloc((size_t)n * sizeof(int));
    int *un = (int *)malloc((size_t)n * sizeof(int));
    int *nun = (int *)malloc((size_t)n * sizeof(int));
    for (int j = 0; j < n; j++) owner[j] = -1;

    double cmax = 0.0;
    for (int i = 0; i < n; i += 5) {
        const double *row = C + (int64_t)i * n;
        for (int j = 0; j < n; j += 17) if (row[j] > cmax) cmax = row[j];
    }
    if (cmax < 1e-6) cmax = 1e-6;
    double eps = cmax * 0.25;
    if (eps < eps_final) eps = eps_final;

    int phases = 0;
    while (phases++ < 30) {
        for (int j = 0; j < n; j++) owner[j] = -1;
        int n_un = n;
        for (int i = 0; i < n; i++) un[i] = i;
        int bids = 0;
        int limit = n * 12;
        while (n_un > 0 && bids < limit) {
            /* bid with the first unassigned only (Gauss-Seidel): fewer conflicts */
            int i = un[0];
            const double *row = C + (int64_t)i * n;
            double best = 1e300, second = 1e300;
            int bj = 0;
            for (int j = 0; j < n; j++) {
                double v = row[j] + price[j];
                if (v < best) {
                    second = best;
                    best = v;
                    bj = j;
                } else if (v < second) {
                    second = v;
                }
            }
            price[bj] += (second - best) + eps;
            int prev = owner[bj];
            owner[bj] = i;
            bids++;
            if (prev >= 0) {
                un[0] = prev; /* replace current unassigned with displaced */
            } else {
                /* remove i from unassigned list (it's at position 0) */
                un[0] = un[--n_un];
            }
        }
        if (n_un == 0) {
            if (eps <= eps_final * 1.001) {
                for (int j = 0; j < n; j++) col_of[owner[j]] = j;
                free(price); free(owner); free(un); free(nun);
                return bids;
            }
            eps *= 0.25;
            if (eps < eps_final) eps = eps_final;
        } else {
            eps *= 0.5;
            if (eps < eps_final * 0.5) {
                free(price); free(owner); free(un); free(nun);
                return -bids;
            }
        }
    }
    free(price); free(owner); free(un); free(nun);
    return -1;
}
