/* Gauss-Seidel auction with a sorted price index so each bid scans columns
   from lowest price and can stop once prices exceed the second-best. */
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

static void sift_down(int *idx, double *price, int start, int end) {
    int root = start;
    while (root * 2 + 1 < end) {
        int child = root * 2 + 1;
        if (child + 1 < end && price[idx[child]] < price[idx[child + 1]]) child++;
        if (price[idx[root]] < price[idx[child]]) {
            int tmp = idx[root]; idx[root] = idx[child]; idx[child] = tmp;
            root = child;
        } else break;
    }
}

/* insertion into a price-sorted (ascending) index. n=600, resorted fully is fine if rare. */
static void sort_idx(int *idx, double *price, int n) {
    /* heapsort ascending by price */
    for (int i = 0; i < n; i++) idx[i] = i;
    for (int start = (n - 2) / 2; start >= 0; start--) sift_down(idx, price, start, n);
    for (int end = n - 1; end > 0; end--) {
        int tmp = idx[end]; idx[end] = idx[0]; idx[0] = tmp;
        sift_down(idx, price, 0, end);
    }
    /* heapsort above yields ascending? sift_down makes max-heap, so result is ascending. yes. */
}

int gsa2_solve(int n, const double *C, int *col_of, double eps_final) {
    double *price = (double *)calloc((size_t)n, sizeof(double));
    int *owner = (int *)malloc((size_t)n * sizeof(int));
