    int *un = (int *)malloc((size_t)n * sizeof(int));
    for (int j = 0; j < n; j++) owner[j] = -1;

    double cmax = 0.0;
    for (int i = 0; i < n; i += 5) {
        const double *row = C + (int64_t)i * n;
        for (int j = 0; j < n; j += 17) if (row[j] > cmax) cmax = row[j];
    }
    if (cmax < 1e-6) cmax = 1e-6;
    double eps = cmax * 0.25;
    if (eps < eps_final) eps = eps_final;

    int phases = 0;
    while (phases++ < 30) {
        for (int j = 0; j < n; j++) owner[j] = -1;
        sort_idx(idx, price, n);
        int n_un = n;
        for (int i = 0; i < n; i++) un[i] = i;
        int bids = 0;
        int limit = n * 12;
        int dirty = 0;
        while (n_un > 0 && bids < limit) {
            if (dirty) { sort_idx(idx, price, n); dirty = 0; }
            int i = un[0];
            const double *row = C + (int64_t)i * n;
            double best = 1e300, second = 1e300;
            int bj = 0;
            /* scan low price to high; stop when price alone cannot beat second */
            for (int t = 0; t < n; t++) {
                int j = idx[t];
                double pj = price[j];
                if (pj >= second) break;          /* row[j] >= 0 assumed */
                double v = row[j] + pj;
                if (v < best) { second = best; best = v; bj = j; }
                else if (v < second) second = v;
            }
            double new_price = price[bj] + (second - best) + eps;
            price[bj] = new_price;
            dirty = 1;
            int prev = owner[bj];
            owner[bj] = i;
            bids++;
            if (prev >= 0) un[0] = prev;
            else un[0] = un[--n_un];
        }
        if (n_un == 0) {
            if (eps <= eps_final * 1.001) {
