/* Batch auction: each round, every unassigned row scans the matrix and bids.
   Conflicts resolved by keeping the highest bid. Uses AVX-friendly row scans
   but the win is processing many rows per price state... actually each row
   still scans. This version is the parallel auction (Jacobi), fewer rounds
   if we keep prices, but each round is n scans. Likely slower.
   Instead: process 1 row but prefetch next rows. Not helpful.
   Real idea: blocked scan of 4 unassigned rows together so price[] is loaded
   once for 4 rows. 4x less price traffic, row traffic unchanged (unavoidable).
*/
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <immintrin.h>

int batch_solve(int n, const double *C, int *col_of, double eps_final) {
    double *price = (double *)calloc((size_t)n, sizeof(double));
    int *owner = (int *)malloc((size_t)n * sizeof(int));
    int *un = (int *)malloc((size_t)n * sizeof(int));
    for (int j = 0; j < n; j++) owner[j] = -1;

    double cmax = 0.0;
    for (int i = 0; i < n; i += 5) {
        const double *row = C + (int64_t)i * n;
        for (int j = 0; j < n; j += 17) if (row[j] > cmax) cmax = row[j];
    }
    if (cmax < 1e-6) cmax = 1e-6;
    double eps = cmax * 0.25;
    if (eps < eps_final) eps = eps_final;

    int phases = 0;
    while (phases++ < 30) {
        for (int j = 0; j < n; j++) owner[j] = -1;
        int n_un = n;
        for (int i = 0; i < n; i++) un[i] = i;
        int bids = 0;
        int limit = n * 20;
        while (n_un > 0 && bids < limit) {
            int batch = n_un < 4 ? n_un : 4;
            int rows[4];
            double best[4], second[4];
            int bestj[4];
            const double *rp[4];
            for (int b = 0; b < batch; b++) {
                rows[b] = un[b];
                best[b] = 1e300; second[b] = 1e300; bestj[b] = 0;
                rp[b] = C + (int64_t)rows[b] * n;
            }
            for (int j = 0; j < n; j++) {
                double pj = price[j];
                for (int b = 0; b < batch; b++) {
                    double val = rp[b][j] + pj;
                    if (val < best[b]) { second[b] = best[b]; best[b] = val; bestj[b] = j; }
                    else if (val < second[b]) second[b] = val;
                }
            }
            /* apply bids sequentially; later bids in the batch see updated prices
               only if we recompute — for correctness of auction, recompute if conflict.
               Simpler: apply one, and if a later row's best column price changed, rescan that row. */
            int consumed = 0;
            for (int b = 0; b < batch; b++) {
                int i = rows[b];
                int bj = bestj[b];
                double inc_base = second[b] - best[b];
                /* if price changed since scan, skip and leave unassigned */
                if (b > 0) {
                    /* verify best still best? cheap check: recompute val */
                    double val = rp[b][bj] + price[bj];
                    if (val > best[b] + 1e-15) {
                        /* stale, put back */
                        un[consumed++] = i;
                        continue;
                    }
                }
                price[bj] += inc_base + eps;
                int prev = owner[bj];
                owner[bj] = i;
                bids++;
                if (prev >= 0 && prev != i) {
                    /* prev might be in this batch and already processed, or earlier */
                    int in_batch_later = 0;
                    un[consumed++] = prev;
                }
            }
            /* append unprocessed tail */
            for (int t = batch; t < n_un; t++) un[consumed++] = un[t];
            n_un = consumed;
            if (batch == 0) break;
        }
        if (n_un == 0) {
            if (eps <= eps_final * 1.001) {
                for (int j = 0; j < n; j++) col_of[owner[j]] = j;
                free(price); free(owner); free(un);
                return bids;
            }
            eps *= 0.25;
            if (eps < eps_final) eps = eps_final;
        } else {
            eps *= 0.5;
            if (eps < eps_final * 0.5) {
                free(price); free(owner); free(un);
                return -bids;
            }
        }
    }
    free(price); free(owner); free(un);
    return -1;
}
